// SPDX-License-Identifier: Apache-2.0
// msfcore boot ROM: IMEM words 0..127 (128 x 16), read with a registered
// address (the same 1-cycle latency as the SRAM macro). Contents = tt_um_msf_bootrom_data.v,
// generated by `python test/assembler.py` from test/bootloader.s (boot
// protocol v2: framed UART / parallel loader with CRC-8 and ACK/NAK).
`default_nettype none

module tt_um_msf_bootrom (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [6:0] a,
    output wire [15:0] q
);
  reg [15:0] rom [0:127];
`include "tt_um_msf_bootrom_data.v"   // initial block: fills rom[0..127]
  // v3: the read resets to word 0, so the decode stage has the first instruction
  // in the first cycle after reset while the core already fetches word 1
  // (tt_um_msf_ctrl.v, imem_raddr). An asynchronous reset like every other
  // flop's: the fetch address never depends on rst_n combinationally.
  //
  // v4 (branch rom-areg): the register holds the address, not the word. The
  // output is the same in every cycle (q = rom[a of the cycle before], and word 0
  // after reset, as ROM_W0 = rom[0]), but the 128-word lookup moves out of the
  // fetch cycle. With the word registered, the fetch address (from the next
  // owner and next PCs) and then the lookup (8.2 ns) made the slow corner's only
  // failing paths at 20 ns: -1.40 ns, every other path +2.17 ns or better (CI GDS
  // run 44351742340). After it, the lookup runs beside the SRAM macro's own
  // read (6.7 ns clock-to-output at the slow corner), whose paths have +3.52 ns.
  reg [6:0] a_r;
  always @(posedge clk or negedge rst_n)
    if (!rst_n) a_r <= 7'd0;
    else        a_r <= a;
  assign q = rom[a_r];
endmodule
